// ============================================================================
// MOTOR DE TRANSPOSIÇÃO E RESOLUÇÃO HARMÔNICA
// ============================================================================

export class ProgressionsLibraryEngine {
  /**
   * Decide automaticamente se o tom selecionado no Ciclo das Quintas usa bemóis ou sustenidos.
   */
  public static shouldPreferFlats(keyRoot: PitchClass, mode: TonalMode): boolean {
    return mode === 'major'
      ? FLAT_MAJOR_KEYS.has(keyRoot)
      : FLAT_MINOR_KEYS.has(keyRoot);
  }

  /**
   * Converte um PitchClass (0..11) para o nome da nota (ex: 1 -> "Db" ou "C#").
   */
  public static getNoteName(pc: PitchClass, preferFlats: boolean): string {
    return preferFlats ? NOTE_NAMES_FLAT[pc] : NOTE_NAMES_SHARP[pc];
  }

  /**
   * Retorna todas as progressões filtradas por categoria ou compatibilidade com o modo atual.
   */
  public static getProgressions(filter?: {
    category?: ProgressionCategory;
    mode?: TonalMode;
  }): ProgressionTemplate[] {
    return FAMOUS_PROGRESSIONS.filter((prog) => {
      if (filter?.category && prog.category !== filter.category) return false;
      if (filter?.mode && prog.targetMode !== filter.mode) return false;
      return true;
    });
  }

  /**
   * Transpõe uma progressão completa para a tonalidade ativa no Ciclo das Quintas,
   * calculando cifras, notas MIDI para o sintetizador e escalas exatas para improvisação.
   */
  public static transposeProgression(
    progressionId: string,
    keyRoot: PitchClass,
    options?: {
      useTetrads?: boolean;
      forceFlats?: boolean;
    }
  ): TransposedProgressionStep[] {
    const template = FAMOUS_PROGRESSIONS.find((p) => p.id === progressionId);
    if (!template) {
      throw new Error(`Progressão não encontrada: ${progressionId}`);
    }

    const useTetrads = options?.useTetrads ?? true;
    const preferFlats =
      options?.forceFlats !== undefined
        ? options.forceFlats
        : this.shouldPreferFlats(keyRoot, template.targetMode);

    return template.steps.map((step, index) => {
      const chordRoot = ((keyRoot + step.semitoneOffset) % 12) as PitchClass;
      const rootName = this.getNoteName(chordRoot, preferFlats);
      const quality = useTetrads ? step.tetradQuality : step.triadQuality;
      const chordSpec = CHORD_INTERVALS[quality];

      // 1. Notas do Acorde e MIDI Voicing (Oitava 3/4 para piano/guitarra + Oitava 1/2 para baixo)
      const chordNotes = chordSpec.intervals.map((interval) =>
        this.getNoteName(((chordRoot + interval) % 12) as PitchClass, preferFlats)
      );

      // Mantém o baixo na região grave natural do contrabaixo (E1 = 28 até D#2 = 39)
      const bassMidiNote = chordRoot >= 4 ? 24 + chordRoot : 36 + chordRoot;

      // Voicing fechado/ergonômico na região média (C3 = 48 .. B4 = 71) para o sintetizador e piano
      const baseMidOctave = chordRoot <= 5 ? 60 : 48;
      const chordMidiNotes = chordSpec.intervals.map(
        (interval) => baseMidOctave + chordRoot + interval
      );

      // 2. Resolução da Escala Principal de Improvisação para este acorde
      const primaryScaleDef = SCALE_DEFINITIONS[step.recommendedScale];
      const scalePitchClasses = primaryScaleDef.intervals.map(
        (interval) => ((chordRoot + interval) % 12) as PitchClass
      );
      const scaleNotes = scalePitchClasses.map((pc) =>
        this.getNoteName(pc, preferFlats)
      );

      // 3. Resolução da Escala Secundária (opcional, ex: Pentatônica)
      let secondaryScaleResolved: TransposedProgressionStep['secondaryScale'];
      if (step.secondaryScale) {
        const secDef = SCALE_DEFINITIONS[step.secondaryScale];
        const secPitchClasses = secDef.intervals.map(
          (interval) => ((chordRoot + interval) % 12) as PitchClass
        );
        secondaryScaleResolved = {
          id: secDef.id,
          name: secDef.name,
          fullTitle: `${rootName} ${secDef.name}`,
          pitchClasses: secPitchClasses,
          notes: secPitchClasses.map((pc) => this.getNoteName(pc, preferFlats)),
        };
      }

      return {
        stepIndex: index,
        measureNumber: index + 1,
        romanDegree: step.romanDegree,
        rootPitchClass: chordRoot,
        rootName,
        chordQuality: quality,
        chordSymbol: `${rootName}${chordSpec.suffix}`,
        chordNotes,
        chordMidiNotes,
        bassMidiNote,
        durationBeats: step.durationBeats,
        harmonicFunction: step.harmonicFunction,
        scale: {
          id: primaryScaleDef.id,
          name: primaryScaleDef.name,
          fullTitle: `${rootName} ${primaryScaleDef.name}`,
          notes: scaleNotes,
          pitchClasses: scalePitchClasses,
          degreeLabels: primaryScaleDef.degreeLabels,
          improvisationTip: primaryScaleDef.improvisationTip,
        },
        secondaryScale: secondaryScaleResolved,
      };
    });
  }
}
